#!/usr/bin/env python3
"""Build directly addressable static pages. Approved media lives in docs/media."""
from pathlib import Path
from html import escape as E
import json,shutil
ROOT=Path(__file__).resolve().parents[1];DOCS=ROOT/'docs'
LANGS=json.loads((ROOT/'src/content.json').read_text())['languages']
VERSION='1.11.0';TAG='v1.11.0-preview.1';BASE='https://dk-bluegrain.github.io/bsc-pages'
RELEASE=f'https://github.com/dk-bluegrain/bsc-pages/releases/download/{TAG}'
(DOCS/'assets').mkdir(parents=True,exist_ok=True)
for name in ('style.css','site.js','mark.svg'):shutil.copy2(ROOT/'src'/name,DOCS/'assets'/name)
(DOCS/'.nojekyll').touch()
captions=json.loads((ROOT/'src/captions.json').read_text())['languages']
media=json.loads((ROOT/'src/media.json').read_text()) if (ROOT/'src/media.json').exists() else {}
def languages(lang,prefix,privacy=False):
 return f'<nav class="languages" aria-label="{dict(es='Idioma',en='Language',de='Sprache',fr='Langue',ru='Язык',uk='Мова',pt='Idioma')[lang]}">'+''.join(f'<a lang="{code}" hreflang="{code}" href="{prefix}{code}/{"privacy/" if privacy else ""}"'+(' aria-current="page"' if code==lang else '')+f'>{E(value["name"])}</a>' for code,value in LANGS.items())+'</nav>'
def header(lang,prefix,privacy=False):
 return f'<header><div class="wrap header"><a class="brand" href="{prefix}{lang}/"><img width="38" height="38" src="{prefix}assets/mark.svg" alt=""><span>Santa Cruz Modern<small>Android · 1.11.0</small></span></a>{languages(lang,prefix,privacy)}</div></header>'
def video(id,lang,prefix,c):
 info=media.get(id,{});tracks=''.join(f'<track kind="captions" srclang="{code}" label="{E(value["name"])}" src="{prefix}media/captions/{code}/{id}.vtt"'+(' default' if code==lang else '')+'>' for code,value in LANGS.items())
 return f'''<div class="video-shell"><video id="video-{id}" controls playsinline preload="none" poster="{prefix}media/{id}.jpg" aria-label="{E(c['overviewTitle'] if id=='overview' else next(x['title'] for x in c['chapters'] if x['id']==id))}"><source src="{prefix}media/{id}.mp4" type="video/mp4">{tracks}</video></div><div class="video-tools"><span class="meta">{info.get('durationLabel','')} · MP4</span><label for="speed-{id}">{E(c['speedLabel'])}</label><select id="speed-{id}" data-speed="video-{id}"><option value="0.5">0.5×</option><option value="0.75">0.75×</option><option value="1" selected>1×</option><option value="1.25">1.25×</option><option value="1.5">1.5×</option><option value="2">2×</option></select></div>'''
def downloads(c):
 return f'''<div class="actions"><a class="button" href="{RELEASE}/santa-cruz-modern-{VERSION}-demo.apk">{E(c['demoAction'])} <span aria-hidden="true">↗</span></a><a class="button secondary" href="#editions">{E(c['liveTitle'])} <span aria-hidden="true">↓</span></a></div>'''
def page(lang,prefix,privacy=False):
 c=LANGS[lang]
 if privacy:
  body=f'<main id="main" class="wrap policy"><a href="../../{lang}/">← Santa Cruz Modern</a><h1>{E(c["privacyTitle"])}</h1><p>{E(c["privacyIntro"])}</p>'+''.join(f'<h2>{E(s["title"])}</h2><p>{E(s["body"])}</p>' for s in c['privacySections'])+f'<p><a href="{prefix}privacy/app/{lang}.html">{E(c["privacyLabel"])} · Android APK</a></p><p><a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub · {E(c["privacyLabel"])}</a></p><p class="meta">2026-10-16 · {VERSION} (26)</p></main>'
 else:
  chapters=''
  for i,ch in enumerate(c['chapters']):
   info=media.get(ch['id'],{});shots=info.get('screenshots',[f'{ch["id"]}-01.jpg'])
   gallery=''.join(f'<button class="shot-button" data-enlarge="{prefix}media/{shot}" aria-label="{E(ch["title"])} · {E(c["screenshotsLabel"])} {j+1}"><img loading="lazy" width="108" height="240" src="{prefix}media/{shot}" alt="{E(ch["title"])} · {E(c["simulatedLabel"])} · {j+1}"></button>' for j,shot in enumerate(shots))
   chapters+=f'''<article class="chapter" id="{ch['id']}"><span class="tag">{E(c['demoLabel'] if ch['id']=='accounts' else c['simulatedLabel'])}</span><h3>{i+1:02d} / {E(ch['title'])}</h3><p>{E(ch['body'])}</p>{video(ch['id'],lang,prefix,c)}<details><summary>{E(c['transcriptLabel'])}</summary>{''.join(f'<p>{E(cue)}</p>' for cue in captions[lang][ch['id']])}</details><h4>{E(c['screenshotsLabel'])}</h4><div class="shot-list">{gallery}</div><p class="subtle">{E(ch['notes'])}</p></article>'''
  chapter_nav=''.join(f'<a href="#{ch["id"]}"><span>{i+1:02d}</span>{E(ch["title"])}</a>' for i,ch in enumerate(c['chapters']))
  steps=''.join(f'<li>{E(step)}</li>' for step in c['installSteps'])
  body=f'''<main id="main"><section class="wrap hero"><div><div class="eyebrow">Android · ES / EN / DE / FR / RU / UK / PT</div><h1>{E(c['tagline'])}</h1><p class="lead">{E(c['intro'])}</p>{downloads(c)}<p class="subtle">Android 8.0+ · {E(c['demoLabel'])} · <a href="#overview">{E(c['overviewTitle'])} ↘</a></p></div><div class="phone-stage"><button class="phone" data-enlarge="{prefix}media/hero.jpg" aria-label="{E(c['screenshotsLabel'])}"><img width="540" height="1200" src="{prefix}media/hero.jpg" alt="{E(c['chapters'][3]['title'])} · {E(c['demoLabel'])}"></button><div class="badge"><strong>Santa Cruz Modern</strong><br>{E(c['demoLabel'])} · DOP / USD</div></div></section><div class="wrap"><aside class="warning">{E(c['warning'])}</aside></div><section id="overview" class="wrap section overview"><div><span class="number">01 / SANTA CRUZ MODERN</span><h2>{E(c['overviewTitle'])}</h2><p>{E(c['overviewBody'])}</p><details><summary>{E(c['transcriptLabel'])}</summary>{''.join(f'<p>{E(cue)}</p>' for cue in captions[lang]['overview'])}</details></div><div>{video('overview',lang,prefix,c)}</div></section><section id="chapters" class="wrap section"><div class="section-heading"><div><span class="number">02 / ANDROID</span><h2>{E(c['chaptersTitle'])}</h2></div><p>{E(c['overviewBody'])}</p></div><div class="chapter-layout"><nav class="chapter-list" aria-label="{E(c['chaptersTitle'])}">{chapter_nav}</nav><div>{chapters}</div></div></section><section id="editions" class="wrap section"><span class="number">03 / APK</span><h2>{E(c['compareTitle'])}</h2><div class="edition-grid"><article class="edition"><span class="meta">.demo · {E(c["demoLabel"])}</span><h3>{E(c['demoTitle'])}</h3><p>{E(c['demoBody'])}</p><a class="button" href="{RELEASE}/santa-cruz-modern-{VERSION}-demo.apk">{E(c['demoAction'])} ↗</a></article><article class="edition"><span class="meta">APK · {E(c["liveTitle"])}</span><h3>{E(c['liveTitle'])}</h3><p>{E(c['liveBody'])}</p><a class="button secondary" href="{RELEASE}/santa-cruz-modern-{VERSION}-live.apk">{E(c['liveAction'])} ↗</a></article></div><p class="subtle">{E(c['versionLabel'])} {VERSION} (26) · <a href="{RELEASE}/SHA256SUMS">SHA-256</a> · <a href="https://github.com/dk-bluegrain/bsc-pages/releases/tag/{TAG}">GitHub Release</a></p><p class="warning">{E(c['warning'])}</p></section><section class="wrap section installation"><div><span class="number">04 / ANDROID 8.0+</span><h2>{E(c['requirementsTitle'])}</h2><p>{E(c['requirementsBody'])}</p><p><a href="{prefix}{lang}/privacy/">{E(c['privacyLabel'])}</a></p><p><a href="{prefix}privacy/app/{lang}.html">{E(c['privacyLabel'])} · Android APK</a></p></div><div><h3>{E(c['installTitle'])}</h3><ol>{steps}</ol></div></section><section class="wrap section"><h2>{E(c['supportLabel'])}</h2><p>{E(c['supportBody'])}</p><a class="button secondary" href="https://github.com/dk-bluegrain/bsc-pages/issues">GitHub ↗</a></section></main><dialog aria-label="{E(c['screenshotsLabel'])}"><img alt=""><button type="button">{E(c['closeLabel'])}</button></dialog>'''
 footer=f'<footer><div class="wrap footer"><span>© 2026 Santa Cruz Modern · Android</span><div class="footer-links"><a href="{prefix}{lang}/privacy/">{E(c["privacyLabel"])}</a><a href="https://github.com/dk-bluegrain/bsc-pages">GitHub</a><a href="{RELEASE}/SHA256SUMS">SHA-256</a></div></div></footer>'
 canonical=BASE+f'/{lang}/'+('privacy/' if privacy else '')
 return f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#143e34"><meta name="description" content="{E(c['intro'])}"><meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self'; media-src 'self'; connect-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'"><meta name="referrer" content="no-referrer"><title>Santa Cruz Modern · {E(c['privacyTitle'] if privacy else c['title'])}</title><link rel="canonical" href="{canonical}">{''.join(f'<link rel="alternate" hreflang="{code}" href="{BASE}/{code}/{"privacy/" if privacy else ""}">' for code in LANGS)}<link rel="icon" href="{prefix}assets/mark.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}assets/style.css"><script src="{prefix}assets/site.js" defer></script></head><body><a class="skip" href="#main">{E(c['skipLabel'])}</a>{header(lang,prefix,privacy)}{body}{footer}</body></html>'''
for lang in LANGS:
 p=DOCS/lang;p.mkdir(exist_ok=True);(p/'index.html').write_text(page(lang,'../'))
 (p/'privacy').mkdir(exist_ok=True);(p/'privacy/index.html').write_text(page(lang,'../../',True))
(DOCS/'index.html').write_text(page('es','./'))
(DOCS/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+BASE+'/sitemap.xml\n')
(DOCS/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{BASE}/{lang}/{suffix}</loc></url>' for lang in LANGS for suffix in ('','privacy/'))+'</urlset>')
print('Built Spanish default, seven language pages and seven localized privacy pages.')
